package co.com.empresa.infrastructure.config.kafka;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.springframework.boot.kafka.autoconfigure.KafkaProperties;import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;import org.springframework.kafka.core.*;import org.springframework.kafka.listener.DefaultErrorHandler;import static org.junit.jupiter.api.Assertions.assertNotNull;import static org.junit.jupiter.api.Assertions.assertTrue;class KafkaConfigBeanCreationTest {    private KafkaProperties kafkaProperties;    private KafkaConfig kafkaConfig;    @BeforeEach    void setUp() {        kafkaProperties = new KafkaProperties();        kafkaConfig = new KafkaConfig(kafkaProperties);    }    @Test    @DisplayName("producerFactory: Should create ProducerFactory with correct serializers")    void producerFactory_CreatesWithSerializers() {        ProducerFactory<String, Object> factory = kafkaConfig.producerFactory();        assertNotNull(factory, "ProducerFactory should not be null");        assertTrue(factory instanceof DefaultKafkaProducerFactory, "Should be DefaultKafkaProducerFactory");    }    @Test    @DisplayName("kafkaTemplate: Should create KafkaTemplate")    void kafkaTemplate_CreatesSuccessfully() {        KafkaTemplate<String, Object> template = kafkaConfig.kafkaTemplate();        assertNotNull(template, "KafkaTemplate should not be null");    }    @Test    @DisplayName("consumerFactory: Should create ConsumerFactory with correct deserializers")    void consumerFactory_CreatesWithDeserializers() {        ConsumerFactory<String, Object> factory = kafkaConfig.consumerFactory();        assertNotNull(factory, "ConsumerFactory should not be null");        assertTrue(factory instanceof DefaultKafkaConsumerFactory, "Should be DefaultKafkaConsumerFactory");    }    @Test    @DisplayName("kafkaListenerContainerFactory: Should create ConcurrentKafkaListenerContainerFactory")    void kafkaListenerContainerFactory_CreatesSuccessfully() {        ConcurrentKafkaListenerContainerFactory<String, Object> factory = kafkaConfig.kafkaListenerContainerFactory();        assertNotNull(factory, "KafkaListenerContainerFactory should not be null");    }    @Test    @DisplayName("kafkaErrorHandler: Should create DefaultErrorHandler with 2 retries")    void kafkaErrorHandler_HasTwoRetries() {        DefaultErrorHandler errorHandler = kafkaConfig.kafkaErrorHandler();        assertNotNull(errorHandler, "ErrorHandler should not be null");        assertTrue(errorHandler instanceof DefaultErrorHandler, "Should be DefaultErrorHandler");    }    @Test    @DisplayName("kafkaTransactionManager: Should create KafkaTransactionManager")    void kafkaTransactionManager_CreatesSuccessfully() {        ProducerFactory<String, Object> producerFactory = kafkaConfig.producerFactory();        assertNotNull(producerFactory, "ProducerFactory should not be null");    }}